try {
  // Access document.cookie using the DOM
  const cookieString = document.cookie;

  // Split the string into individual cookies
  const cookies = cookieString.split(';');

  // Filter for 'session_id'
  const sessionIdCookie = cookies.find((cookie) => {
    return (
      cookie.trim() === 'session_id' ||
      (cookie.includes('session_id=') && cookie.includes('='))
    );
  });

  if (sessionIdCookie) {
    console.log(sessionIdCookie);
  }
} catch (error) {
  console.error(error); // DOM access fails
}

// If you're running this in Node.js environment, use the cookie module.
const express = require('express');
const app = express();

app.use((req, res, next) => {
  const cookies = req.cookies;

  if (cookies.session_id) {
    console.log(cookies.session_id);
  }

  next();
});

// Set up a route to test
