// Function to get auth token from localStorage
function getAuthToken() {
    try {
        // Get the stored data
        const storedData = window.localStorage.getItem('auth_data');

        if (storedData) {
            // Parse JSON data
            const jsonData = JSON.parse(storedData);

            // Check if 'auth_token' key exists in data
            if ('auth_token' in jsonData) {
                return jsonData['auth_token'];
            }
        }
    } catch (error) {
        console.error('Error accessing localStorage:', error);
    }

    // Return null or a default value if auth token not found
    return null;
}

// Example usage:
const authToken = getAuthToken();
if (authToken) {
    console.log(`Auth Token: ${authToken}`);
} else {
    console.log('No Auth Token Found');
}
```

